CREATE TABLE IF NOT EXISTS sys_users (id VARCHAR(64) PRIMARY KEY,username VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL,status ENUM('active','disabled') NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS hub_groups (id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,status VARCHAR(16) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS hub_group_members (group_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES hub_groups(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS hub_providers (provider VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,status VARCHAR(16) NOT NULL,last_synced_at DATETIME(6) NULL);
CREATE TABLE IF NOT EXISTS hub_models (id VARCHAR(64) PRIMARY KEY,provider VARCHAR(64) NOT NULL,upstream_model_id VARCHAR(191) NOT NULL,name VARCHAR(191) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,available BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE KEY hub_model_upstream(provider,upstream_model_id),FOREIGN KEY(provider) REFERENCES hub_providers(provider));
CREATE TABLE IF NOT EXISTS hub_grants (subject_type ENUM('user','group') NOT NULL,subject_id VARCHAR(64) NOT NULL,model_id VARCHAR(64) NOT NULL,PRIMARY KEY(subject_type,subject_id,model_id),FOREIGN KEY(model_id) REFERENCES hub_models(id));
CREATE TABLE IF NOT EXISTS hub_conversations (id VARCHAR(64) PRIMARY KEY,owner_id VARCHAR(64) NOT NULL,model_id VARCHAR(64) NOT NULL,pi_session_ref VARCHAR(128) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,hidden BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,FOREIGN KEY(model_id) REFERENCES hub_models(id));
CREATE TABLE IF NOT EXISTS hub_usage_records (request_id VARCHAR(64) PRIMARY KEY,conversation_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,model_id VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,input_tokens BIGINT NULL,output_tokens BIGINT NULL,cached_tokens BIGINT NULL,total_tokens BIGINT NULL,started_at DATETIME(6) NOT NULL,ended_at DATETIME(6) NOT NULL,INDEX hub_usage_filter(user_id,model_id,started_at));
CREATE TABLE IF NOT EXISTS hub_audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,action VARCHAR(80) NOT NULL,object_type VARCHAR(40) NOT NULL,object_id VARCHAR(64) NOT NULL,result VARCHAR(16) NOT NULL,trace_id VARCHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX hub_audit_filter(actor_id,action,created_at));
